function stockHeader(){const a=asset(),m=E.metrics(series(a.code));return `<section class="panel panel-space"><div class="panel-body stock-summary"><div class="stock-header"><div class="stock-emblem">${a.name[0]}</div><div><h2 style="font-size:21px">${a.name} <span class="stock-code">${a.code}</span></h2><div class="stock-meta"><span>${a.industry}</span>${pill(a.type==='etf'?'ETF适配':'公司研究','good')}${a.shortHistory?pill('短样本','warn'):''}</div></div></div><div style="text-align:right"><div class="stock-price num">${num(m?.price,m?.price<10?3:2)}</div><div class="small ${cls(m?.change)}">${change(m?.change)} · ${mode==='local'?(series(a.code).at(-1)?.completed===false?'盘中价格':'日线收盘'):isDemo()?'合成价格':'快照价格'}</div>${liveQuoteLine(a.code)}</div></div><div class="panel-note">${sourceLine(a.code)}</div></section>`}
function radar(){const f=obs(state.code)?.fundamentals,m=E.metrics(series(state.code)),vals=[m?.ret20!==null&&m?.ret20!==undefined?.75:0,f&&E.valid(f.roe)?.75:0,f&&E.valid(f.pe)?.75:0,series(state.code).some(x=>E.valid(x.netFlow))?.75:0,m?.ma60?.75:0,0,0],cx=135,cy=112,r=76,pt=(i,k)=>[cx+Math.sin(i/7*2*Math.PI)*r*k,cy-Math.cos(i/7*2*Math.PI)*r*k];return `<svg class="radar" viewBox="0 0 270 225" role="img" aria-label="七维覆盖示意，不是综合评分">${[.3,.6,1].map(k=>`<polygon points="${vals.map((_,i)=>pt(i,k).join(',')).join(' ')}" fill="none" stroke="#e5ecef"/>`).join('')}<polygon points="${vals.map((v,i)=>pt(i,v).join(',')).join(' ')}" fill="#087f7418" stroke="#087f74" stroke-width="1.5"/>${['行业','基本面','估值','资金','技术','情绪','事件'].map((n,i)=>{const p=pt(i,1.24);return `<text x="${p[0]}" y="${p[1]+3}" text-anchor="middle" font-size="10" fill="#75879a">${n}</text>`}).join('')}</svg>`}
function research(){const a=asset(),d=DIMENSIONS[state.dimension],s=latestSignal(a.code);return title('个股七维分析','研究事实、解释与反证分开，七维覆盖不等于买入概率。',selectAsset()+button('信号与回测',"go('backtest')",true,'smile'))+stockHeader()+`<div class="three-states"><div class="state-block"><small>研究证据</small><strong>财务与事件待核实</strong><p>${isDemo()?'合成数值仅用于体验分析结构':'财务与事件尚未连接，不生成判断'}</p></div><div class="state-block warn"><small>技术研究信号</small><strong>${s?s.date+' · '+(s.type==='buy'?s.grade+'级笑脸':'哭脸'):'暂无足够信号样本'}</strong><p>最近已形成信号，不表示今天仍有效</p></div><div class="state-block"><small>下一步研究</small><strong>${a.type==='etf'?'成分结构与申赎':'验证研究逻辑与反证'}</strong><p>问题性质在证据不足时保持不确定</p></div></div><div class="research-layout"><aside class="panel"><div class="panel-head"><h2>七维研究地图</h2>${pill('覆盖示意')}</div>${radar()}<ul class="dimension-list">${DIMENSIONS.map((v,i)=>`<li><button class="${i===state.dimension?'active':''}" onclick="state.dimension=${i};render()"><span>0${i+1} ${a.type==='etf'&&i===1?'成分与盈利':v.name}</span>${icon('arrow')}</button></li>`).join('')}</ul><div class="panel-note">图形表示字段可用性，不表示研究质量或投资评分；情绪和事件尚缺证据。</div></aside><section class="panel"><div class="dimension-summary"><div class="chip-line">${pill('0'+(state.dimension+1)+' / '+d.name,'good')}${pill('真实证据待补齐')}</div><h2 style="margin-top:12px">${d.title}</h2><p>${a.questions[state.dimension%3]}</p></div>${dimensionReadings()}${d.fields.map(([n,t])=>`<div class="evidence-row"><div class="label">${n}</div><div><p>${a.type==='etf'&&state.dimension===1?'从成分权重、整体盈利和集中度验证，不把基金当成经营公司。':t}</p><div class="source">${state.dimension===4?'信号由当前模式的完整历史样本计算':'待接入公开披露与可追溯数据'}</div></div><div class="evidence-status">${pill(state.dimension===4?'可计算':'待验证',state.dimension===4?'good':'neutral')}</div></div>`).join('')}<div class="conclusion"><h3>需要重新评估的条件</h3><p>${d.invalidate}</p></div><div class="conclusion" style="border-top:1px solid var(--line)"><h3>${a.name} · 研究问题</h3><ul class="research-questions">${a.questions.map(q=>`<li>${q}</li>`).join('')}</ul><div class="actions">${button('进入对应模块',`go('${d.page}')`,true)}${button('写研究记录',"noteDialog()",false,'plan')}</div></div></section></div>`}
function dimensionReadings(){const a=asset(),m=E.metrics(series(a.code)),bm=E.metrics(series('510300')),f=obs(a.code)?.fundamentals||{},net=series(a.code).slice(-5).map(b=>b.netFlow),flows=net.length===5&&net.every(E.valid)?net.reduce((x,y)=>x+y,0)/1e8:null;
 const rows=[
 [['近20日表现',change(m?.ret20)],['相对沪深300ETF',E.valid(m?.ret20)&&E.valid(bm?.ret20)?num(m.ret20-bm.ret20)+'个百分点':'—']],
 [['收入增速',a.type==='stock'?change(f.revenueGrowth):'成分盈利待接入'],['现金流 / 净利润',a.type==='stock'?num(f.cashRatio)+'×':'成分权重待接入']],
 [['PE / PB',a.type==='stock'?num(f.pe,1)+' / '+num(f.pb,1):'指数加权估值待接入'],['PS',a.type==='stock'?num(f.ps,1):'亏损股处理待确认']],
 [['近5日资金统计',E.valid(flows)?num(flows)+'亿元':'—'],['近日报价量比',num(m?.vr)]],
 [['MA20 / MA60',num(m?.ma20,3)+' / '+num(m?.ma60,3)],['20日年化波动',change(m?.vol20)]],
 [['近120观察日表现',change(m?.ret120)],['距60日最高收盘',change(m?.drawdown)]],
 [['上市日期',a.listed||'未纳入快照'],['后续事件', '原文与披露时间待补齐']]
 ][state.dimension];return `<div class="dimension-readings">${rows.map(([t,v])=>`<div><small>${t}</small><strong class="num">${v}</strong></div>`).join('')}<p>${mode==='local'?'真实价格 · 财务与事件待接入':isDemo()?'价格和财务为合成示例':'仅使用导入字段'} · 指标不替代证据判断</p></div>`}
function attribution(i){const s=SKILL_MAP[i];return `<div class="skill-attribution"><span>应用技能</span><strong>${s.name}</strong><span>${s.detail}</span></div>`}
function sentiment(){const a=asset();return title('市场情绪偏离','先验证基本面，再讨论情绪是否偏离现实。',selectAsset())+attribution(0)+(a.type==='etf'?notice('ETF分析行业与成分情绪；财务健康需穿透成分，不套用单一公司标准。'):'')+`<div class="metrics">${metric('近120观察日表现',change(E.metrics(series(a.code))?.ret120),isDemo()?'合成近半年代理':'不足120条则不计算')}${metric('财务健康检查','待核实','利润 / 现金 / 偿债 / 审计 / ST')}${metric('问题性质','不确定','证据不足，不强行判定错杀')}${metric('偏差综合评分','—','缺少真实情绪与基本面证据')}</div><div class="grid-two">${panel(a.name+' · 叙事与现实对照',`<div class="table-wrap"><table class="wrap-table"><thead><tr><th>待验证叙事</th><th>需要的事实证据</th><th>状态</th></tr></thead><tbody>${[['需求下滑只是短期波动','订单、交付、价格与收入同周期对照'],['跌得多所以已经便宜','估值、盈利修正与行业可比样本'],['行业即将触底','供需、库存、现金流与验证时间'],['资金流出说明经营恶化','交易分类与公司经营事实分开']].map(([l,r])=>`<tr><td>${l}</td><td>${r}</td><td>${pill('不确定')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('两层验证：财务与竞争力',`<div class="panel-body">${[['财务健康','扣非利润、经营现金流、短期偿债、审计与退市风险'],['竞争优势','市场份额、毛利率、研发、客户与管理层'],['问题分类','暂时性 / 结构性 / 不确定；保留支持及反对证据'],['催化剂','披露日期、兑现条件、失败后果；不编造概率']].map(([n,t])=>`<div class="rule-row"><div><strong>${n}</strong><p>${t}</p></div>${pill('待验证')}</div>`).join('')}</div>`)}</div>${panel('问题性质研究卡',`<div class="panel-body"><div class="three-states"><div class="state-block"><small>暂时性假设</small><strong>周期或一次性扰动</strong><p>需要恢复路径与验证时间。</p></div><div class="state-block danger"><small>结构性假设</small><strong>盈利模式或竞争力受损</strong><p>价格下跌本身不足以否定这一假设。</p></div><div class="state-block warn"><small>当前归类</small><strong>不确定</strong><p>不输出缺乏证据的逆向机会排名。</p></div></div><div class="actions">${button('记录判断与反证',"noteDialog('情绪偏离')",true,'plan')}${button('继续检查估值',"go('valuation')")}</div></div>`)}<div style="margin-top:18px">${notice('技能所列历史回归概率缺乏可核验样本，本页不展示。北向数据按实际可得披露口径处理，不把缺失补0。')}</div>`}
function valuation(){const a=asset(),f=obs(a.code)?.fundamentals,v=k=>f?.[k];return title('估值与基本面','把倍数放进企业阶段、增长和现金创造中。',selectAsset())+attribution(1)+(a.type==='etf'?etfValuation():`<div class="metrics">${metric('PE（TTM）',num(v('pe'),1),isDemo()?'合成财务示例':'需确认利润与时点口径')}${metric('PB / PS',num(v('pb'),1)+' / '+num(v('ps'),1),'不采用跨行业统一贵贱阈值')}${metric('收入 / 利润增速',num(v('revenueGrowth'),1)+'% / '+num(v('profitGrowth'),1)+'%','需核对报告期与基数')}${metric('经营现金 / 净利润',num(v('cashRatio'),2)+'×','非正利润时单独解释')}</div><div class="grid-main">${panel(a.name+' · 盈利质量检查',`<div class="table-wrap"><table class="wrap-table"><thead><tr><th>维度</th><th>${isDemo()?'合成示例':'快照字段'}</th><th>解释与复核条件</th></tr></thead><tbody>${[['毛利率',num(v('grossMargin'),1)+'%','与细分同行及历史周期比较'],['ROE',num(v('roe'),1)+'%','检查杠杆与一次性损益'],['研发资本化比例',num(v('rdCapitalization'),1)+'%','核对资本化理由、摊销与历年变化'],['股份支付 / 收入',num(v('sbcRevenue'),1)+'%','核对报表已计入的费用，不重复扣减'],['概念相关收入','待披露验证','概念标签不能代替收入和交付'],['自由现金流','待原始报表核实','检查经营现金与资本支出定义']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}${panel('适配企业阶段',`<div class="panel-body">${[['稳定盈利','PE / PEG / 现金流情景'],['盈利初期','PS、利润率与盈利拐点'],['亏损或投入期','PS / EV收入、单位经济与现金消耗'],['周期性公司','中周期盈利、价格和成本']].map(([n,t])=>`<div class="rule-row"><div><strong>${n}</strong><p>${t}</p></div></div>`).join('')}</div>`)}</div>${panel('预期与倍数敏感性实验',`<div class="panel-body"><p class="small muted">仅在“每股收益×PE”适用时观察相对变化，不是目标价预测。</p><div class="fields-two" style="margin-top:16px"><div class="field"><div class="range-label"><label for="earnings-shock">盈利相对变化</label><strong id="earnings-value">0%</strong></div><input id="earnings-shock" type="range" min="-50" max="50" value="0" oninput="valuationScenario()"></div><div class="field"><div class="range-label"><label for="multiple-shock">估值倍数相对变化</label><strong id="multiple-value">0%</strong></div><input id="multiple-shock" type="range" min="-50" max="50" value="0" oninput="valuationScenario()"></div></div><div class="scenario-result"><span>（1 + 盈利变化）×（1 + 倍数变化）− 1</span><strong id="scenario-value" class="num">0.00%</strong></div></div>`)}<div style="margin-top:18px">${notice('不将固定政策溢价、统一PE/PS区间、“40法则”作为全科技通用结论。股份支付按报表/调整口径核对，避免重复扣减；亏损、极低基数和周期公司不机械套PEG。')}</div>`)}
function etfValuation(){return `<div class="grid-two">${panel(asset().name+' · ETF口径',`<div class="panel-body">${[['成分估值','注明指数加权、亏损股处理与报告日'],['盈利质量','成分盈利、行业分布及头部权重'],['份额与规模','份额变化与净值变化分别处理'],['交易与跟踪','折溢价、流动性、费率及跟踪误差']].map(([n,t])=>`<div class="rule-row"><div><strong>${n}</strong><p>${t}</p></div>${pill('待接入')}</div>`).join('')}</div>`)}${panel('与公司研究分开',`<div class="panel-body"><p class="muted">不用基金自身经营利润计算公司PE。两只ETF不进入六只股票的财务因子排名。</p><div class="actions" style="margin-top:20px">${button('看市场趋势',"go('market')",true)}${button('看K线信号',"go('backtest')")}</div></div>`)}</div>`}
function valuationScenario(){const e=Number($('#earnings-shock').value),p=Number($('#multiple-shock').value),v=((1+e/100)*(1+p/100)-1)*100;$('#earnings-value').textContent=change(e);$('#multiple-value').textContent=change(p);$('#scenario-value').textContent=change(v);$('#scenario-value').className='num '+cls(v)}
function factors(){const rows=E.factorRows(data(),state.weights),eligible=rows.filter(r=>r.total!==null),sum=state.weights.reduce((a,b)=>a+b,0);return title('多因子筛选','在明确样本与口径内比较，缺失项不默认为中性分。',button('等权基准',"factorPreset('equal')")+button('短样本适配',"factorPreset('short')",true))+attribution(2)+notice('比较池为当前'+rows.length+'只A股自选股票，跨行业小样本，未实施行业中性，不等同全A股选股。港美股与ETF不参与A股截面排名；长期动量与风险因子样本不足时留空。')+`<div class="factor-layout"><aside class="panel"><div class="panel-head"><h2>因子权重</h2>${pill('自动归一')}</div><div class="panel-body">${FACTOR_DEFS.map((f,i)=>`<div class="field"><div class="range-label"><label for="weight-${i}">${f.name}</label><strong>${sum?num(state.weights[i]/sum*100,1):'0'}%</strong></div><input id="weight-${i}" type="range" min="0" max="10" value="${state.weights[i]}" onchange="state.weights[${i}]=Number(this.value);render()"></div>`).join('')}<p class="small muted">子指标至少3个可比样本。启用因子缺失时，不生成综合分。</p></div></aside><div><div class="submetrics"><div class="submetric"><label>A股股票样本</label><strong>${rows.length}</strong><small>港美股与ETF已排除</small></div><div class="submetric"><label>可排名样本</label><strong>${eligible.length}</strong><small>依当前权重</small></div><div class="submetric"><label>比较方式</label><strong style="font-size:18px">非行业中性</strong><small>跨行业自选池</small></div><div class="submetric"><label>数据环境</label><strong style="font-size:18px">${mode==='local'?'本地真实行情':isDemo()?'合成示例':'导入快照'}</strong><small>非投资推荐</small></div></div>${panel('自选因子画像与排名',`<div class="table-wrap"><table><thead><tr><th>排序 / 标的</th>${FACTOR_DEFS.map(f=>`<th>${f.name}</th>`).join('')}<th>综合</th><th>覆盖</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><button class="stock-link" onclick="setAsset('${r.asset.code}','research')"><span class="stock-name">${r.total!==null?i+1:'—'} ${r.asset.name}</span><span class="stock-code">${r.asset.code}</span></button></td>${FACTOR_DEFS.map(f=>`<td class="num factor-cell" style="background:${r.scores[f.id]!==null?'rgba(8,127,116,'+(r.scores[f.id]/100*.12)+')':'transparent'}">${num(r.scores[f.id],0)}</td>`).join('')}<td class="num"><strong>${num(r.total,1)}</strong></td><td>${num(r.coverage*100,0)}% ${r.total===null?pill('不排名','warn'):''}</td></tr>`).join('')}</tbody></table></div>`)}<div style="margin-top:18px">${panel('因子定义与约束',`<div class="panel-body factor-defs">${FACTOR_DEFS.map(f=>`<div><h3>${f.name}</h3><p>${f.parts.map(p=>p[3]+' '+num(p[1]*100,0)+'%').join(' / ')}</p></div>`).join('')}</div><div class="panel-note">子指标在可用截面2.5%/97.5%处缩尾，平均秩处理并列，再按权重合成。宏观择时、拥挤度与无来源历史溢价不自动填充。</div>`)}</div></div></div>`}
function factorPreset(w){state.weights=w==='short'?[1,0,1,0,1,1]:[1,1,1,1,1,1];render();toast(w==='short'?'停用长期动量与低波，统一使用四因子':'恢复六因子等权基准')}
